import{b as d,O as e,g as r,j as a}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"附录A · Oracle 常用命令速查表","description":"","frontmatter":{},"headers":[],"relativePath":"database/oracle/appendix/cheatsheet/index.md","filePath":"数据库管理/Oracle从入门到精通/附录/A.常用命令速查.md","lastUpdated":1782140566000}'),o={name:"database/oracle/appendix/cheatsheet/index.md"};function c(E,t,h,T,A,l){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="附录a-·-oracle-常用命令速查表" tabindex="-1">附录A · Oracle 常用命令速查表 <a class="header-anchor" href="#附录a-·-oracle-常用命令速查表" aria-label="Permalink to &quot;附录A · Oracle 常用命令速查表&quot;">​</a></h1><h2 id="数据库管理" tabindex="-1">数据库管理 <a class="header-anchor" href="#数据库管理" aria-label="Permalink to &quot;数据库管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>启动数据库</td><td><code>STARTUP</code></td></tr><tr><td>关闭数据库</td><td><code>SHUTDOWN IMMEDIATE</code></td></tr><tr><td>查看数据库状态</td><td><code>SELECT STATUS FROM V$INSTANCE;</code></td></tr><tr><td>查看数据库名</td><td><code>SELECT NAME FROM V$DATABASE;</code></td></tr><tr><td>查看版本</td><td><code>SELECT * FROM V$VERSION;</code></td></tr><tr><td>查看归档模式</td><td><code>ARCHIVE LOG LIST;</code></td></tr></tbody></table><h2 id="表管理" tabindex="-1">表管理 <a class="header-anchor" href="#表管理" aria-label="Permalink to &quot;表管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>查看所有表</td><td><code>SELECT table_name FROM user_tables;</code></td></tr><tr><td>查看表结构</td><td><code>DESC 表名;</code></td></tr><tr><td>查看建表SQL</td><td><code>SELECT DBMS_METADATA.GET_DDL(&#39;TABLE&#39;,&#39;表名&#39;) FROM dual;</code></td></tr><tr><td>重命名表</td><td><code>RENAME 旧名 TO 新名;</code></td></tr><tr><td>删除表</td><td><code>DROP TABLE 表名;</code></td></tr><tr><td>清空表</td><td><code>TRUNCATE TABLE 表名;</code></td></tr></tbody></table><h2 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to &quot;约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>查看约束</td><td><code>SELECT * FROM user_constraints WHERE table_name=&#39;表名&#39;;</code></td></tr><tr><td>添加主键</td><td><code>ALTER TABLE 表名 ADD CONSTRAINT 约束名 PRIMARY KEY(列);</code></td></tr><tr><td>添加外键</td><td><code>ALTER TABLE 表名 ADD CONSTRAINT 约束名 FOREIGN KEY(列) REFERENCES 父表(列);</code></td></tr><tr><td>禁用约束</td><td><code>ALTER TABLE 表名 DISABLE CONSTRAINT 约束名;</code></td></tr><tr><td>启用约束</td><td><code>ALTER TABLE 表名 ENABLE CONSTRAINT 约束名;</code></td></tr><tr><td>删除约束</td><td><code>ALTER TABLE 表名 DROP CONSTRAINT 约束名;</code></td></tr></tbody></table><h2 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>创建索引</td><td><code>CREATE INDEX 索引名 ON 表名(列);</code></td></tr><tr><td>创建唯一索引</td><td><code>CREATE UNIQUE INDEX 索引名 ON 表名(列);</code></td></tr><tr><td>查看索引</td><td><code>SELECT * FROM user_indexes WHERE table_name=&#39;表名&#39;;</code></td></tr><tr><td>重建索引</td><td><code>ALTER INDEX 索引名 REBUILD;</code></td></tr><tr><td>删除索引</td><td><code>DROP INDEX 索引名;</code></td></tr></tbody></table><h2 id="视图" tabindex="-1">视图 <a class="header-anchor" href="#视图" aria-label="Permalink to &quot;视图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>创建视图</td><td><code>CREATE OR REPLACE VIEW 视图名 AS SELECT ...;</code></td></tr><tr><td>查看视图</td><td><code>SELECT view_name FROM user_views;</code></td></tr><tr><td>查看视图定义</td><td><code>SELECT text FROM user_views WHERE view_name=&#39;视图名&#39;;</code></td></tr><tr><td>删除视图</td><td><code>DROP VIEW 视图名;</code></td></tr></tbody></table><h2 id="序列" tabindex="-1">序列 <a class="header-anchor" href="#序列" aria-label="Permalink to &quot;序列&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>创建序列</td><td><code>CREATE SEQUENCE 序列名 START WITH 1 INCREMENT BY 1;</code></td></tr><tr><td>取下一个值</td><td><code>SELECT 序列名.NEXTVAL FROM dual;</code></td></tr><tr><td>取当前值</td><td><code>SELECT 序列名.CURRVAL FROM dual;</code></td></tr><tr><td>查看序列</td><td><code>SELECT * FROM user_sequences;</code></td></tr><tr><td>删除序列</td><td><code>DROP SEQUENCE 序列名;</code></td></tr></tbody></table><h2 id="用户与权限" tabindex="-1">用户与权限 <a class="header-anchor" href="#用户与权限" aria-label="Permalink to &quot;用户与权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>创建用户</td><td><code>CREATE USER 用户名 IDENTIFIED BY &quot;密码&quot;;</code></td></tr><tr><td>授权</td><td><code>GRANT 权限 TO 用户名;</code></td></tr><tr><td>收回权限</td><td><code>REVOKE 权限 FROM 用户名;</code></td></tr><tr><td>锁定用户</td><td><code>ALTER USER 用户名 ACCOUNT LOCK;</code></td></tr><tr><td>解锁用户</td><td><code>ALTER USER 用户名 ACCOUNT UNLOCK;</code></td></tr><tr><td>删除用户</td><td><code>DROP USER 用户名 CASCADE;</code></td></tr></tbody></table><h2 id="执行计划与统计" tabindex="-1">执行计划与统计 <a class="header-anchor" href="#执行计划与统计" aria-label="Permalink to &quot;执行计划与统计&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>解释计划</td><td><code>EXPLAIN PLAN FOR SELECT ...;</code></td></tr><tr><td>显示计划</td><td><code>SELECT * FROM TABLE(DBMS_XPLAN.DISPLAY);</code></td></tr><tr><td>收集统计信息</td><td><code>EXEC DBMS_STATS.GATHER_TABLE_STATS(&#39;用户名&#39;,&#39;表名&#39;);</code></td></tr><tr><td>开启 AUTOTRACE</td><td><code>SET AUTOTRACE ON;</code></td></tr></tbody></table><h2 id="常用视图" tabindex="-1">常用视图 <a class="header-anchor" href="#常用视图" aria-label="Permalink to &quot;常用视图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>视图</th><th>用途</th></tr></thead><tbody><tr><td><code>V$INSTANCE</code></td><td>实例状态</td></tr><tr><td><code>V$DATABASE</code></td><td>数据库信息</td></tr><tr><td><code>V$SESSION</code></td><td>当前会话</td></tr><tr><td><code>V$SQL</code></td><td>缓存的 SQL</td></tr><tr><td><code>V$LOCK</code></td><td>锁信息</td></tr><tr><td><code>V$SGA</code></td><td>SGA 信息</td></tr><tr><td><code>DBA_TABLES</code></td><td>所有表</td></tr><tr><td><code>DBA_USERS</code></td><td>所有用户</td></tr><tr><td><code>DBA_DATA_FILES</code></td><td>数据文件</td></tr><tr><td><code>USER_TABLES</code></td><td>当前用户的表</td></tr><tr><td><code>USER_INDEXES</code></td><td>当前用户的索引</td></tr></tbody></table><h2 id="闪回" tabindex="-1">闪回 <a class="header-anchor" href="#闪回" aria-label="Permalink to &quot;闪回&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>闪回查询</td><td><code>SELECT * FROM 表名 AS OF TIMESTAMP (SYSTIMESTAMP - INTERVAL &#39;5&#39; MINUTE);</code></td></tr><tr><td>闪回表</td><td><code>FLASHBACK TABLE 表名 TO TIMESTAMP ...;</code></td></tr><tr><td>闪回删除</td><td><code>FLASHBACK TABLE 表名 TO BEFORE DROP;</code></td></tr><tr><td>查看回收站</td><td><code>SELECT * FROM user_recyclebin;</code></td></tr><tr><td>清空回收站</td><td><code>PURGE RECYCLEBIN;</code></td></tr></tbody></table>',21)])])}const R=d(o,[["render",c]]);export{b as __pageData,R as default};
